let translations={},currentLanguage="en";function initLanguageSystem(e="en"){const n=localStorage.getItem("preferred_language"),t=document.documentElement.lang.toLowerCase();currentLanguage=n?n.toLowerCase():t||e,loadTranslations(currentLanguage),initLanguageToggle()}async function loadTranslations(e){try{const n=await fetch(`/js/locales/${e}.json`);if(!n.ok)throw new Error(`Failed to load ${e} translations`);translations=await n.json(),console.log(`Loaded ${e} translations`)}catch(e){console.error("Error loading translations:",e),translations={}}}function t(e,n={}){const t=e.split(".");let a=translations;for(const n of t){if(!a||"object"!=typeof a||!(n in a))return e;a=a[n]}return"string"!=typeof a?e:Object.entries(n).reduce((e,[n,t])=>e.replace(new RegExp(`{{${n}}}`,"g"),t),a)}function switchLanguage(e){if(e===currentLanguage)return;currentLanguage=e,localStorage.setItem("preferred_language",e);let n=window.location.pathname.split("/").pop();if(n&&!n.includes("index")){let t=n.split(".")[0].replace(/-fr$/,"")+("fr"===e?"-fr":"")+".html";window.location.href=t}else{let n="fr"===e?"index-fr.html":"index.html";window.location.href=n}}function initLanguageToggle(){console.log("Language toggle: Using native HTML links");document.querySelectorAll(".language-toggle").forEach(e=>{e.addEventListener("click",function(e){const n=this.textContent.trim().toLowerCase();localStorage.setItem("preferred_language",n)})})}window.t=t,window.switchLanguage=switchLanguage,window.initLanguageSystem=initLanguageSystem;